  const stockRequests: RepairStockCheckRequest[] = partLineItems.map(li => ({
    partId: li.partId!,
    requestedQuantity: Number(li.quantity),
  }))

  // Step 5: Validate stock availability
  const stockResult = await validateRepairStockAvailability(stockRequests)
  if (!stockResult.valid) {
    throw new InsufficientStockForRepairError(stockResult.shortfalls)
  }

