// ============================================================================
// Public API — Complete Repair Payment (completion flow)
// ============================================================================

/**
 * Complete a repair by collecting payment, deducting stock for parts used,
 * creating a linked Sale record with sourceType='repair', and marking the
 * repair as completed.
 *
 * This is an all-or-nothing completion flow: if any step fails (stock check,
 * sequence generation, DB insert), everything rolls back via SQLite transaction.
 *
 * Flow:
 * 1. Validate repair exists and is in 'ready' status
 * 2. Compute total from line items (pricing port)
 * 3. Validate payment amounts match the computed total
 * 4. Check stock availability for all parts used (stock port)
 * 5. Atomic transaction: create sale → create sale line items → create payments →
 *    create payment allocations → deduct stock via movements → mark repair completed
 *
 * @param id - Repair identifier (must be in 'ready' status)
 * @param input - Payment data (single or split methods)
 * @returns CompleteRepairResult with created entities
 */
export async function completeRepairPayment(
  id: string,
  input: CompleteRepairPaymentInput,
): Promise<CompleteRepairResult> {
  const validated = { payments: input.payments }

  if (validated.payments.length === 0) {
    throw new Error('At least one payment method is required')
  }

  // Step 1: Look up current repair state and validate it's in 'ready' status
  const current = await findRepairById(id)
  if (!current) {
    throw new RepairNotFoundError(id)
  }
  if (current.status !== 'ready') {
    throw new RepairNotReadyError(current.status as string)
  }

  // Resolve customerId from repair → bicycle → customer
  const [bicycle] = await db.select().from(bicycles).where(eq(bicycles.id, current.bicycleId))
  let saleCustomerId: string | null = null
  if (bicycle?.customerId) {
    const [cust] = await db.select().from(customers).where(eq(customers.id, bicycle.customerId))
    saleCustomerId = cust?.id ?? null
  }

  // Step 2: Fetch all line items and compute the expected total gross (pricing port)
  const lineItems = await findLineItemsByRepairId(id)
  if (lineItems.length === 0) {
    throw new Error('Cannot complete a repair with no line items')
  }

  const pricing = computeRepairTotals(lineItems)

  // Step 3: Validate payment total matches expected gross total
  const paidTotal = validated.payments.reduce((sum, p) => sum + p.amount, 0)
  if (paidTotal !== pricing.totalGross) {
    throw new PaymentMismatchError(pricing.totalGross, paidTotal)
  }

  // Step 4: Aggregate stock requests from part line items only
  const partLineItems = lineItems.filter(li => li.lineType === 'part')
  const stockRequests = partLineItems.map(li => ({
    partId: li.partId!,
    requestedQuantity: Number(li.quantity),
  }))

  // Step 5: Validate stock availability (stock port)
  const stockResult = await validateRepairStockAvailability(stockRequests)
  if (!stockResult.valid) {
    throw new InsufficientStockForRepairError(stockResult.shortfalls)
  }

  // Step 6: Execute single atomic transaction — all inserts or nothing
  const now = Date.now()

  // Declare arrays before the try block so they're accessible in the return statement
  const createdPayments: Array<{ id: string; method: 'cash' | 'card' | 'bank_transfer'; amount: number }> = []
  const createdMovements: Array<{ id: string; partId: string; quantityDelta: number; reason: string; referenceType: string; referenceId: string }> = []

  try {
    // Begin transaction
    run('BEGIN TRANSACTION')

    // Create linked sale (cross-aggregate seam)
    const { saleId, saleNumber } = await createLinkedSale(
      id,
      saleCustomerId,
      lineItems,
      pricing.subtotalNet,
      pricing.vatTotal,
      pricing.totalGross,
    )

    // Insert payment records and allocations for each payment method
    for (const pay of validated.payments) {
      const paymentId = crypto.randomUUID()
      run(
        'INSERT INTO payments (id, method, amount, created_at) VALUES (?, ?, ?, ?)',
        [paymentId, pay.method, pay.amount, now]
      )

      // Insert payment allocation → sale
      run(
        'INSERT INTO payment_allocations (id, payment_id, target_type, target_id, allocated_amount) VALUES (?, ?, ?, ?, ?)',
        [crypto.randomUUID(), paymentId, 'sale', saleId, pay.amount]
      )

      createdPayments.push({ id: paymentId, method: pay.method as 'cash' | 'card' | 'bank_transfer', amount: pay.amount })
    }

    // Insert stock movements (negative deltas for parts used)
    for (const li of partLineItems) {
      const movementId = crypto.randomUUID()
      run(
        'INSERT INTO stock_movements (id, part_id, quantity_delta, reason, reference_type, reference_id, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)',
        [movementId, li.partId!, -Number(li.quantity), 'repair_use', 'sale', saleId, now]
      )

      createdMovements.push({
        id: movementId,
        partId: li.partId!,
        quantityDelta: -Number(li.quantity),
        reason: 'repair_use',
        referenceType: 'sale',
        referenceId: saleId,
      })
    }

    // Update repair status to completed with completedAt timestamp
    run(
      'UPDATE repairs SET status = ?, completed_at = ? WHERE id = ?',
      ['completed', now, id]
    )

    // Record the final status transition in audit trail
    await recordStatusTransition(id, 'completed')

    // Commit transaction
    run('COMMIT')
  } catch (err) {
    // Rollback on any error
    try { run('ROLLBACK') }
    catch {}
    throw err
  }

  // Step 7: Fetch and return the updated repair + created entities
  const [updatedRepair] = await db.select().from(repairs).where(eq(repairs.id, id))

  if (!updatedRepair) {
    throw new RepairNotFoundError(id)
  }

  return {
    repair: {
      id: updatedRepair.id,
      bicycleId: updatedRepair.bicycleId,
      assignedTo: updatedRepair.assignedTo,
      status: 'completed' as const,
      customerNotes: updatedRepair.customerNotes,
      internalNotes: updatedRepair.internalNotes,
      holdReason: null, // cleared on completion
      holdReasonNote: null,
      plannedDate: updatedRepair.plannedDate ?? null,
      pickupDate: updatedRepair.pickupDate ?? null,
      completedAt: now,
      createdAt: updatedRepair.createdAt,
    },
    sale: {
      id: saleId,
      saleNumber,
      customerId: saleCustomerId,
      sourceType: 'repair',
      sourceId: id,
      status: 'completed',
      subtotalNet: pricing.subtotalNet,
      vatTotal: pricing.vatTotal,
      totalGross: pricing.totalGross,
    },
    payments: createdPayments,
    stockMovements: createdMovements,
  }
}

