import { describe, it, expect, beforeEach } from 'vitest'
import crypto from 'crypto'
import type Database from 'better-sqlite3'
import { db, sqliteDb } from '@/db/index.js'
import {
  customers,
  bicycles,
  repairs,
  repairLineItems,
  repairStatusHistory,
  parts,
  laborServices,
  vatRates,
  workLogs,
  stockMovements,
  sales,
  saleLineItems,
  payments as paymentsTable,
  paymentAllocations,
  type Customer as DbCustomer,
  type Bicycle as DbBicycle,
} from '@/db/schema.js'
import { eq } from 'drizzle-orm'

// Import the completion module directly (not through facade)
import { completeRepairPayment } from '../completion.js'
import { RepairNotReadyError, PaymentMismatchError, InsufficientStockForRepairError } from '../completion.errors.js'
import type { CompleteRepairResult, CompleteRepairPaymentInput } from '../completion.types.js'
import { computeRepairTotals } from '../pricing.js'
import { validateRepairStockAvailability } from '../stock.js'

// Import helpers needed to set up test data (from repair.service.ts facade)
import { createRepairIntake, transitionRepairStatus, createRepairLineItem } from '../../repair.service.js'

/** Raw SQL executor for test fixtures (avoids Drizzle Date/number conversion) */
function run(sqlStr: string, params?: unknown[]): void {
  const client = sqliteDb as Database.Database
  client.prepare(sqlStr).run(...(params ?? []))
}

// ---------------------------------------------------------------------------
// Test fixture helpers
// ---------------------------------------------------------------------------

async function createTestCustomer(): Promise<DbCustomer> {
  const id = crypto.randomUUID()
  run(
    'INSERT INTO customers (id, type, first_name, last_name, company_name, vat_id, phone, email, street, number, bus, postal_code, city, country, notification_preference) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
    [id, 'private', 'Jane', 'Doe', null, null, '+32470123456', 'jane@example.com', null, null, null, null, null, 'BE', null]
  )

  const [result] = await db.select().from(customers).where(eq(customers.id, id))
  return result!
}

async function createTestBicycle(customerId: string): Promise<DbBicycle> {
  const id = crypto.randomUUID()
  const now = Date.now()
  run(
    'INSERT INTO bicycles (id, source, template_id, customer_id, brand, model, year, color, frame_size, status, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
    [id, 'customer_owned', null, customerId, 'Trek', 'Fuel EX', 2023, 'Green', 'L', 'inventory', now]
  )

  const [result] = await db.select().from(bicycles).where(eq(bicycles.id, id))
  return result!
}

async function createTestCustomerWithBicycle(): Promise<{ customerId: string; bicycleId: string }> {
  const customer = await createTestCustomer()
  const bicycle = await createTestBicycle(customer.id)
  return { customerId: customer.id, bicycleId: bicycle.id }
}

async function createTestRepair(bicycleId: string): Promise<string> {
  const id = crypto.randomUUID()
  const now = Date.now()
  run(
    'INSERT INTO repairs (id, bicycle_id, assigned_to, status, customer_notes, internal_notes, hold_reason, hold_reason_note, planned_date, pickup_date, completed_at, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
    [id, bicycleId, null, 'intake', null, null, null, null, null, null, null, now]
  )

  // Record initial status transition
  run(
    'INSERT INTO repair_status_history (id, repair_id, status, transitioned_at) VALUES (?, ?, ?, ?)',
    [crypto.randomUUID(), id, 'intake', now]
  )

  return id
}

async function createTestPartWithStock(name: string, quantityOnHand: number): Promise<{ id: string }> {
  const partId = crypto.randomUUID()
  // Create the part record with denormalized quantity_on_hand
  run(
    'INSERT INTO parts (id, name, sku, description, unit_price_net, cost_price, quantity_on_hand, reorder_level, category, supplier_id, is_active) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
    [partId, name, `SKU-${name.toUpperCase().replace(/\s+/g, '-')}`, null, 0, 0, quantityOnHand, 5, 'general', null, true]
  )

  // Create the stock movement that represents initial stock (positive delta)
  const now = Date.now()
  run(
    'INSERT INTO stock_movements (id, part_id, quantity_delta, reason, reference_type, reference_id, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)',
    [crypto.randomUUID(), partId, quantityOnHand, 'initial_stock', null, null, now]
  )

  return { id: partId }
}

async function createTestLaborService(name: string, billingType: 'hourly' | 'flat_rate', price: number): Promise<string> {
  const id = crypto.randomUUID()
  run(
    'INSERT INTO labor_services (id, name, description, billing_type, hourly_rate, flat_rate_price, is_active) VALUES (?, ?, ?, ?, ?, ?, ?)',
    [id, name, null, billingType, price, price, true]
  )
  return id
}

async function createTestVatRate(ratePercent: number): Promise<string> {
  const id = crypto.randomUUID()
  run(
    'INSERT INTO vat_rates (id, rate_percent, is_active) VALUES (?, ?, ?)',
    [id, ratePercent, true]
  )
  return id
}

// ---------------------------------------------------------------------------
// Tests — Pricing Port (computeRepairTotals) in isolation
// ---------------------------------------------------------------------------

describe('pricing port (computeRepairTotals)', () => {
  it('returns zero totals for empty line items', () => {
    const result = computeRepairTotals([])
    expect(result).toEqual({ subtotalNet: 0, vatTotal: 0, totalGross: 0 })
  })

  it('computes correct totals from a single part line item', () => {
    const result = computeRepairTotals([{
      lineType: 'part',
      lineTotalNet: 1000,
      lineTotalVat: 210,
      lineTotalGross: 1210,
    }])
    expect(result).toEqual({ subtotalNet: 1000, vatTotal: 210, totalGross: 1210 })
  })

  it('sums totals across multiple line items', () => {
    const result = computeRepairTotals([
      { lineType: 'part', lineTotalNet: 1000, lineTotalVat: 210, lineTotalGross: 1210 },
      { lineType: 'labor', lineTotalNet: 5000, lineTotalVat: 1050, lineTotalGross: 6050 },
    ])
    expect(result).toEqual({ subtotalNet: 6000, vatTotal: 1260, totalGross: 7260 })
  })

  it('handles string-encoded numeric values', () => {
    const result = computeRepairTotals([{
      lineType: 'part',
      lineTotalNet: '1000' as unknown as number,
      lineTotalVat: '210' as unknown as number,
      lineTotalGross: '1210' as unknown as number,
    }])
    expect(result).toEqual({ subtotalNet: 1000, vatTotal: 210, totalGross: 1210 })
  })
})

// ---------------------------------------------------------------------------
// Tests — Stock Port (validateRepairStockAvailability) in isolation
// ---------------------------------------------------------------------------

describe('stock port (validateRepairStockAvailability)', () => {
  beforeEach(async () => {
    await db.delete(stockMovements)
    await db.delete(parts)
  })

  it('returns valid=true for empty requests', async () => {
    const result = await validateRepairStockAvailability([])
    expect(result).toEqual({ valid: true, shortfalls: [] })
  })

  it('returns valid=true when stock is sufficient', async () => {
    const partId = (await createTestPartWithStock('Brake Pads', 50)).id
    const result = await validateRepairStockAvailability([{
      partId,
      requestedQuantity: 10,
    }])
    expect(result.valid).toBe(true)
    expect(result.shortfalls).toEqual([])
  })

  it('returns valid=false with shortfalls when stock is insufficient', async () => {
    const partId = (await createTestPartWithStock('Inner Tube', 2)).id
    const result = await validateRepairStockAvailability([{
      partId,
      requestedQuantity: 5,
    }])
    expect(result.valid).toBe(false)
    expect(result.shortfalls).toEqual([
      { partId, requested: 5, available: 2 },
    ])
  })

  it('aggregates multiple parts with mixed availability', async () => {
    const partId1 = (await createTestPartWithStock('Brake Pads', 50)).id
    const partId2 = (await createTestPartWithStock('Inner Tube', 2)).id
    const result = await validateRepairStockAvailability([
      { partId: partId1, requestedQuantity: 1 },
      { partId: partId2, requestedQuantity: 5 },
    ])
    expect(result.valid).toBe(false)
    // Only the shortfall is reported; sufficient parts are omitted
    expect(result.shortfalls).toEqual([
      { partId: partId2, requested: 5, available: 2 },
    ])
  })

  it('sorts shortfalls by partId', async () => {
    const partA = (await createTestPartWithStock('Part A', 1)).id
    const partB = (await createTestPartWithStock('Part B', 0)).id
    // Request in reverse alphabetical order to verify sorting
    const result = await validateRepairStockAvailability([
      { partId: partB, requestedQuantity: 3 },
      { partId: partA, requestedQuantity: 5 },
    ])
    expect(result.shortfalls.map(s => s.partId)).toEqual(
      [partA, partB].sort() // shortfalls are sorted by partId
    )
  })

  it('handles zero stock correctly', async () => {
    const partId = (await createTestPartWithStock('No Stock Part', 0)).id
    const result = await validateRepairStockAvailability([{
      partId,
      requestedQuantity: 1,
    }])
    expect(result.valid).toBe(false)
    expect(result.shortfalls[0]?.available).toBe(0)
  })
})

// ---------------------------------------------------------------------------
// Tests — Complete Repair Payment (completion flow)
// ---------------------------------------------------------------------------

describe('completeRepairPayment', () => {
  let repairId: string
  let partId1: string
  let laborServiceId: string
  let vatRateId: string

  beforeEach(async () => {
    // Clean up all relevant tables
    await db.delete(stockMovements)
    await db.delete(paymentAllocations)
    await db.delete(paymentsTable)
    await db.delete(saleLineItems)
    await db.delete(sales)
    await db.delete(repairStatusHistory)
    await db.delete(repairs)
    await db.delete(bicycles)
    await db.delete(customers)
    await db.delete(repairLineItems)
    await db.delete(workLogs)
    await db.delete(parts)
    await db.delete(laborServices)
    await db.delete(vatRates)

    // Create test customer and bicycle
    const { bicycleId } = await createTestCustomerWithBicycle()
    repairId = await createTestRepair(bicycleId)

    // Create parts with stock
    partId1 = (await createTestPartWithStock('Brake Pads', 50)).id

    // Create labor service
    laborServiceId = await createTestLaborService('Tune-up', 'hourly', 35000)

    // Create VAT rate
    vatRateId = await createTestVatRate(2100)
  })

  it('completes a repair with single cash payment and creates linked sale', async () => {
    // Add line items to the repair
    await createRepairLineItem(repairId, {
      lineType: 'part',
      partId: partId1,
      description: 'Brake Pads (Standard)',
      quantity: 1,
      unitPriceNet: 2500,
      vatRateId,
    })

    // Transition to ready status first
    await transitionRepairStatus(repairId, { targetStatus: 'in_progress' })
    await transitionRepairStatus(repairId, { targetStatus: 'verified' })
    await transitionRepairStatus(repairId, { targetStatus: 'ready' })

    // Act: complete with single cash payment
    const result = await completeRepairPayment(repairId, {
      payments: [{ method: 'cash', amount: 3025 }], // gross total for brake pads + VAT
    }) as CompleteRepairResult

    // Assert repair is completed
    expect(result.repair.status).toBe('completed')
    expect(result.repair.completedAt).toBeDefined()
    expect(typeof result.repair.completedAt).toBe('number')

    // Assert linked sale was created with sourceType='repair'
    expect(result.sale.sourceType).toBe('repair')
    expect(result.sale.sourceId).toBe(repairId)
    expect(result.sale.status).toBe('completed')
    expect(result.sale.totalGross).toBe(3025)

    // Assert payment was created
    expect(result.payments).toHaveLength(1)
    expect(result.payments[0].method).toBe('cash')
    expect(result.payments[0].amount).toBe(3025)

    // Assert stock movement was created for the part used
    expect(result.stockMovements).toHaveLength(1)
    expect(result.stockMovements[0].partId).toBe(partId1)
    expect(result.stockMovements[0].quantityDelta).toBe(-1)
    expect(result.stockMovements[0].reason).toBe('repair_use')
  })

  it('completes a repair with split payment (cash + card)', async () => {
    await createRepairLineItem(repairId, {
      lineType: 'part',
      partId: partId1,
      description: 'Brake Pads',
      quantity: 1,
      unitPriceNet: 2500,
      vatRateId,
    })

    await transitionRepairStatus(repairId, { targetStatus: 'in_progress' })
    await transitionRepairStatus(repairId, { targetStatus: 'verified' })
    await transitionRepairStatus(repairId, { targetStatus: 'ready' })

    const result = await completeRepairPayment(repairId, {
      payments: [
        { method: 'cash', amount: 1500 },
        { method: 'card', amount: 1525 },
      ],
    }) as CompleteRepairResult

    expect(result.payments).toHaveLength(2)
    expect(result.payments[0].method).toBe('cash')
    expect(result.payments[1].method).toBe('card')
    expect(result.payments.reduce((sum, p) => sum + p.amount, 0)).toBe(3025)
  })

  it('throws RepairNotReadyError when repair is not in ready status', async () => {
    // Repair starts in 'intake' status — do NOT transition to ready
    await expect(
      completeRepairPayment(repairId, { payments: [{ method: 'cash', amount: 100 }] })
    ).rejects.toThrow(RepairNotReadyError)

    await expect(
      completeRepairPayment(repairId, { payments: [{ method: 'cash', amount: 100 }] })
    ).rejects.toThrow("Repair must be in 'ready' status to complete")
  })

  it('throws PaymentMismatchError when payment total does not match line items', async () => {
    await createRepairLineItem(repairId, {
      lineType: 'part',
      partId: partId1,
      description: 'Brake Pads',
      quantity: 1,
      unitPriceNet: 2500,
      vatRateId,
    })

    await transitionRepairStatus(repairId, { targetStatus: 'in_progress' })
    await transitionRepairStatus(repairId, { targetStatus: 'verified' })
    await transitionRepairStatus(repairId, { targetStatus: 'ready' })

    // Pay less than the expected total (3025)
    await expect(
      completeRepairPayment(repairId, { payments: [{ method: 'cash', amount: 2000 }] })
    ).rejects.toThrow(PaymentMismatchError)
  })

  it('throws InsufficientStockForRepairError when stock is insufficient', async () => {
    // Create a part with only 1 unit in stock
    const lowStockPartId = (await createTestPartWithStock('Rare Part', 1)).id

    await createRepairLineItem(repairId, {
      lineType: 'part',
      partId: lowStockPartId,
      description: 'Rare Part',
      quantity: 5, // requesting more than available
      unitPriceNet: 1000,
      vatRateId,
    })

    await transitionRepairStatus(repairId, { targetStatus: 'in_progress' })
    await transitionRepairStatus(repairId, { targetStatus: 'verified' })
    await transitionRepairStatus(repairId, { targetStatus: 'ready' })

    const expectedGross = 1000 + Math.round(1000 * (2100 / 10000)) // net + VAT
    await expect(
      completeRepairPayment(repairId, { payments: [{ method: 'cash', amount: expectedGross }] })
    ).rejects.toThrow(InsufficientStockForRepairError)
  })

  it('throws error when repair does not exist', async () => {
    await expect(
      completeRepairPayment('non-existent-id', { payments: [{ method: 'cash', amount: 100 }] })
    ).rejects.toThrow()
  })

  it('throws error when no payment methods provided', async () => {
    await transitionRepairStatus(repairId, { targetStatus: 'in_progress' })
    await transitionRepairStatus(repairId, { targetStatus: 'verified' })
    await transitionRepairStatus(repairId, { targetStatus: 'ready' })

    // Add a line item so it gets past the "no line items" check
    await createRepairLineItem(repairId, {
      lineType: 'part',
      partId: partId1,
      description: 'Brake Pads',
      quantity: 1,
      unitPriceNet: 2500,
      vatRateId,
    })

    await expect(
      completeRepairPayment(repairId, { payments: [] } as CompleteRepairPaymentInput)
    ).rejects.toThrow('At least one payment method is required')
  })

  it('throws error when repair has no line items', async () => {
    // Do NOT add any line items — just transition to ready
    await transitionRepairStatus(repairId, { targetStatus: 'in_progress' })
    await transitionRepairStatus(repairId, { targetStatus: 'verified' })
    await transitionRepairStatus(repairId, { targetStatus: 'ready' })

    await expect(
      completeRepairPayment(repairId, { payments: [{ method: 'cash', amount: 100 }] })
    ).rejects.toThrow('Cannot complete a repair with no line items')
  })

  it('cannot complete the same repair twice (idempotency guard)', async () => {
    await createRepairLineItem(repairId, {
      lineType: 'part',
      partId: partId1,
      description: 'Brake Pads',
      quantity: 1,
      unitPriceNet: 2500,
      vatRateId,
    })

    await transitionRepairStatus(repairId, { targetStatus: 'in_progress' })
    await transitionRepairStatus(repairId, { targetStatus: 'verified' })
    await transitionRepairStatus(repairId, { targetStatus: 'ready' })

    // First completion succeeds
    await completeRepairPayment(repairId, {
      payments: [{ method: 'cash', amount: 3025 }],
    })

    // Second attempt fails because repair is now 'completed', not 'ready'
    await expect(
      completeRepairPayment(repairId, { payments: [{ method: 'cash', amount: 3025 }] })
    ).rejects.toThrow(RepairNotReadyError)
  })

  it('creates correct sale totals with mixed parts and labor line items', async () => {
    // Add a part line item
    await createRepairLineItem(repairId, {
      lineType: 'part',
      partId: partId1,
      description: 'Brake Pads',
      quantity: 2,
      unitPriceNet: 2500,
      vatRateId,
    })

    // Add a labor line item
    await createRepairLineItem(repairId, {
      lineType: 'labor',
      laborServiceId,
      description: 'Tune-up Labor',
      quantity: 1,
      unitPriceNet: 35000,
      vatRateId,
    })

    await transitionRepairStatus(repairId, { targetStatus: 'in_progress' })
    await transitionRepairStatus(repairId, { targetStatus: 'verified' })
    await transitionRepairStatus(repairId, { targetStatus: 'ready' })

    // Compute expected gross: (2 * 2500 + 35000) net + VAT at 21%
    const expectedNet = 2 * 2500 + 35000 // 40000
    const expectedVat = Math.round(40000 * (2100 / 10000)) // 8400
    const expectedGross = expectedNet + expectedVat // 48400

    const result = await completeRepairPayment(repairId, {
      payments: [{ method: 'card', amount: expectedGross }],
    }) as CompleteRepairResult

    expect(result.sale.subtotalNet).toBe(expectedNet)
    expect(result.sale.vatTotal).toBe(expectedVat)
    expect(result.sale.totalGross).toBe(expectedGross)
  })

  it('deducts stock for all parts used in the repair', async () => {
    const partId2 = (await createTestPartWithStock('Inner Tube', 30)).id

    await createRepairLineItem(repairId, {
      lineType: 'part',
      partId: partId1,
      description: 'Brake Pads',
      quantity: 2,
      unitPriceNet: 2500,
      vatRateId,
    })

    await createRepairLineItem(repairId, {
      lineType: 'part',
      partId: partId2,
      description: 'Inner Tube',
      quantity: 1,
      unitPriceNet: 800,
      vatRateId,
    })

    await transitionRepairStatus(repairId, { targetStatus: 'in_progress' })
    await transitionRepairStatus(repairId, { targetStatus: 'verified' })
    await transitionRepairStatus(repairId, { targetStatus: 'ready' })

    const expectedNet = 2 * 2500 + 800 // 5800
    const expectedVat = Math.round(5800 * (2100 / 10000)) // 1218
    const expectedGross = expectedNet + expectedVat

    const result = await completeRepairPayment(repairId, {
      payments: [{ method: 'cash', amount: expectedGross }],
    }) as CompleteRepairResult

    expect(result.stockMovements).toHaveLength(2)
    expect(result.stockMovements.find(m => m.partId === partId1)?.quantityDelta).toBe(-2)
    expect(result.stockMovements.find(m => m.partId === partId2)?.quantityDelta).toBe(-1)
  })
})

