// ============================================================================
// Facade re-exports — repair payment completion flow
//
// The completion flow has been extracted to ./repair/completion.ts for better
// modularity (ADR-008). These re-exports preserve the public surface so that
// all import sites in routes and tests resolve without modification.
// ============================================================================

export {
  completeRepairPayment,
} from './repair/completion.js'

export type {
  CompleteRepairResult,
  CompleteRepairPaymentInput,
} from './repair/completion.types.js'

export {
  RepairNotReadyError,
  PaymentMismatchError,
  InsufficientStockForRepairError,
} from './repair/completion.errors.js'

//
// This is a local helper scoped to the completion flow. The top-level `run()`
// in repair.service.ts serves other sub-domains (lifecycle, line-items, etc.).
// Keeping it here reflects actual usage and avoids forcing unrelated functions
// to depend on this module's transaction pattern.
// ============================================================================

function run(sqlStr: string, params?: unknown[]): void {
  const client = sqliteDb as Database.Database
  client.prepare(sqlStr).run(...(params ?? []))
}

